 SharedPreferences prefs;LinearLayout root;PalView preview;TextView status;boolean pendingOverlay;int pendingNotifications=0;final int ink=0xff3f5147,green=0xff527861;
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable bg(int co,int radius){GradientDrawable d=new GradientDrawable();d.setColor(co);d.setCornerRadius(dp(radius));return d;}
 TextView label(String s,int size,int co){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(co);t.setPadding(0,dp(6),0,dp(6));t.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));return t;}
