 void button(String title,boolean primary,Runnable action){TextView b=label(title,15,primary?Color.WHITE:green);b.setGravity(Gravity.CENTER);b.setBackground(bg(primary?green:0xffe7ede3,18));b.setMinHeight(dp(49));LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,dp(49));l.topMargin=dp(9);root.addView(b,l);b.setOnClickListener(v->action.run());b.setContentDescription(title);}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("pals",0);getWindow().setStatusBarColor(0xfff8f7f0);getWindow().setNavigationBarColor(0xfff8f7f0);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);show();}
 void show(){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(0xfff8f7f0);sc.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(18),dp(22),dp(30));sc.addView(root);setContentView(sc);
 root.addView(label("YOUR POCKET-SIZED HAPPY PLACE",10,green));TextView name=label("PocketPals",34,ink);name.setTypeface(Typeface.create("sans-serif-medium",0));root.addView(name);root.addView(label("A tiny friend for your everyday adventures.",14,0xff83877c));
 preview=new PalView(this,false);preview.setBackground(bg(Color.WHITE,25));preview.setClipToOutline(true);LinearLayout.LayoutParams hero=new LinearLayout.LayoutParams(-1,dp(214));hero.topMargin=dp(12);root.addView(preview,hero);status=label("",14,green);root.addView(status);updateStatus();
 LinearLayout care=new LinearLayout(this);root.addView(care);String[] a={"Feed","Play","Nap"};for(String act:a){TextView b=label(act,14,ink);b.setGravity(Gravity.CENTER);b.setBackground(bg(0xffeee9dc,16));LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(0,dp(44),1);l.setMargins(dp(3),0,dp(3),0);care.addView(b,l);b.setOnClickListener(v->{prefs.edit().putInt("hearts",prefs.getInt("hearts",0)+1).apply();preview.react(act);updateStatus();});}
 heading("Meet your little friends");for(int row=0;row<2;row++){LinearLayout strip=new LinearLayout(this);root.addView(strip);for(int col=0;col<3;col++){final int id=row*3+col;LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setGravity(Gravity.CENTER);card.setPadding(dp(3),dp(6),dp(3),dp(8));boolean sel=id==prefs.getInt("pet",0);GradientDrawable back=bg(sel?0xffe0eadd:0xfff0eee6,18);if(sel)back.setStroke(dp(1),green);card.setBackground(back);LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(0,dp(112),1);l.setMargins(dp(3),dp(4),dp(3),dp(4));strip.addView(card,l);PalView art=new PalView(this,false);art.fixedPet=id;card.addView(art,new LinearLayout.LayoutParams(-1,dp(70)));TextView t=label((sel?"✓ ":"")+PalView.NAMES[id].split(" · ")[0],12,ink);t.setGravity(Gravity.CENTER);card.addView(t);Runnable pick=()->{prefs.edit().putInt("pet",id).apply();show();};card.setOnClickListener(v->pick.run());art.setOnClickListener(v->pick.run());}}
 heading("Choose a happy place");LinearLayout scenes=new LinearLayout(this);root.addView(scenes);for(int i=0;i<3;i++){final int s=i;TextView b=label(new String[]{"Meadow","Sakura","Moonlight"}[i],12,ink);b.setGravity(Gravity.CENTER);b.setBackground(bg(prefs.getInt("scene",0)==i?0xffdee8da:0xffeeeae1,14));LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(0,dp(42),1);l.setMargins(dp(3),0,dp(3),0);scenes.addView(b,l);b.setOnClickListener(v->{prefs.edit().putInt("scene",s).apply();show();});}
 heading("Native Hyper Island");button("Play rain with pet · native media",true,()->{stopService(new Intent(this,IslandService.class));try{startForegroundService(new Intent(this,RainService.class));toast("Playing gentle rain. Check Hyper Island for the media card.");}catch(RuntimeException e){toast("Could not start rain playback.");}});root.addView(label("Plays audible rain for up to 30 minutes. Uses real media playback with your pet as artwork; HyperOS controls the island appearance. Stop below or from the media controls.",13,0xff85877d));root.addView(label("Checks whether your phone grants this app access. Native mode uses Xiaomi’s system notification layout and pet images. Smooth free-moving pets are available in floating mode.",13,0xff85877d));button("Check and try native island",true,()->notificationsThen(1));button("Open notification settings",false,()->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName())));
 heading("Floating companion");root.addView(label("Separate from Hyper Island. A small camera-area pet with smooth animation. Drag to adjust its position.",13,0xff85877d));PalView pill=new PalView(this,true);LinearLayout.LayoutParams pl=new LinearLayout.LayoutParams(dp(160),dp(40));pl.gravity=Gravity.CENTER_HORIZONTAL;pl.topMargin=dp(10);root.addView(pill,pl);
 button("Start floating pet",true,()->notificationsThen(2));button("Stop all pet sessions",false,()->{stopService(new Intent(this,IslandService.class));stopService(new Intent(this,RainService.class));toast("All pet sessions stopped");});button("Set live wallpaper",false,()->{try{startActivity(new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER).putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,PalWallpaper.class)));}catch(ActivityNotFoundException e){toast("Choose PocketPals Meadow from your phone’s wallpaper settings");}});
 root.addView(label("v"+appVersion()+" • Offline • No ads\nNative access is controlled by your phone. Lock-screen wallpaper options depend on the system picker.",12,0xff898c81));
 }
 String appVersion(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "";}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void updateStatus(){int h=prefs.getInt("hearts",0);status.setText(PalView.NAMES[prefs.getInt("pet",0)]+"   ·   Level "+(1+h/10)+"   ·   "+h+" hearts");}
 void notificationsThen(int mode){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingNotifications=mode;requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},10);}else if(mode==1)checkNative();else overlay();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==10){int m=pendingNotifications;pendingNotifications=0;if(g.length>0&&g[0]==android.content.pm.PackageManager.PERMISSION_GRANTED){if(m==1)checkNative();else overlay();}else toast("Allow notifications to use a pet session with a visible Stop control.");}}
 void checkNative(){toast("Checking native island access…");new Thread(()->{int protocol=NativeIsland.protocol(this);Boolean allowed=NativeIsland.permission(this);runOnUiThread(()->{if(isFinishing())return;if(Boolean.TRUE.equals(allowed)){new AlertDialog.Builder(this).setTitle("Native access allowed").setMessage("Your system reports that PocketPals may send focus notifications (protocol "+protocol+"). Start a 30-minute pet session? Appearance is controlled by HyperOS; please check the island after starting.").setPositiveButton("Start",(d,w)->startServiceMode(true)).setNegativeButton("Cancel",null).show();}else{String msg=Boolean.FALSE.equals(allowed)?"HyperOS reports that PocketPals does not have native focus-notification access.":"This firmware did not return a native app-access result.";new AlertDialog.Builder(this).setTitle("Native island not ready").setMessage(msg+"\n\nProtocol reported: "+protocol+"\nAndroid: "+Build.VERSION.RELEASE+"\n\nAn installed APK cannot grant itself Xiaomi’s access. You can check notification settings or use the separately labeled floating pet.").setPositiveButton("Settings",(d,w)->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()))).setNegativeButton("Close",null).show();}});}).start();}
 void overlay(){if(!Settings.canDrawOverlays(this)){pendingOverlay=true;startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}else startServiceMode(false);}
 void startServiceMode(boolean nativeMode){stopService(new Intent(this,RainService.class));try{startForegroundService(new Intent(this,IslandService.class).setAction(nativeMode?"NATIVE":"OVERLAY"));toast(nativeMode?"Native session requested. Check your system island.":"Floating pet started. Drag it to position.");}catch(RuntimeException e){toast("Could not start. Check app permissions and try again.");}}
 protected void onResume(){super.onResume();if(pendingOverlay){pendingOverlay=false;if(Settings.canDrawOverlays(this))startServiceMode(false);}}
